#!/usr/bin/env node
'use strict';

/**
 * Generates the Codex-native command skills in platforms/codex/skills/ from commands/*.md.
 *
 * One skill per command file (commands/_ref is internal and skipped):
 *   platforms/codex/skills/boomopen-workflow-kit-<file>/SKILL.md
 *   platforms/codex/skills/boomopen-workflow-kit-<file>/agents/openai.yaml
 * The skill only points Codex at the command file; the command decides which rules it loads.
 *
 * Usage: node .github/scripts/generate-codex-skills.js [--check]
 *   --check  exit 1 when a generated file is missing or out of date (nothing is written)
 */

const fs = require('node:fs');
const path = require('node:path');

const REPO_ROOT = path.resolve(__dirname, '..', '..');
const COMMANDS_DIR = path.join(REPO_ROOT, 'commands');
const SKILLS_DIR = path.join(REPO_ROOT, 'platforms', 'codex', 'skills');
const SKILL_PREFIX = 'boomopen-workflow-kit-';
const FRAMEWORK = '~/.codex/skills/boomopen-workflow-kit';
const MAX_DESCRIPTION_CHARS = 400;
const DEFAULT_BRAND_COLOR = '#6366F1';
const FRONTMATTER_PATTERN = /^---\r?\n([\s\S]*?)\r?\n---/;
const CONTROL_CHARS = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F-\u009F]/g;

/** Brand colour per base command (kept from the hand-written skills). */
const BRAND_COLORS = {
  ask: '#06B6D4', auto: '#6366F1', brainstorm: '#EC4899', code: '#3B82F6', cook: '#F59E0B',
  debug: '#EF4444', deploy: '#8B5CF6', design: '#EC4899', docs: '#14B8A6', fix: '#EF4444',
  plan: '#6366F1', report: '#10B981', research: '#0EA5E9', review: '#10B981', test: '#10B981',
};

/** Reads a scalar `description:` from YAML frontmatter (plain or double-quoted). */
function readDescription(text) {
  const match = FRONTMATTER_PATTERN.exec(text.replace(/^﻿/, ''));
  if (!match) return '';
  const lines = match[1].split(/\r?\n/);
  const index = lines.findIndex((l) => /^description:/.test(l));
  if (index === -1) return '';
  const raw = lines[index].slice('description:'.length).trim();
  let value = raw;
  if (/^[>|][+-]?$/.test(raw)) {
    // Block scalar: the indented lines that follow.
    const block = [];
    for (const next of lines.slice(index + 1)) {
      if (!/^\s+\S/.test(next) && next.trim() !== '') break;
      block.push(next.trim());
    }
    value = block.join(' ');
  } else if (raw.startsWith('"') && raw.endsWith('"')) {
    try {
      value = JSON.parse(raw);
    } catch {
      value = raw.slice(1, -1);
    }
  } else if (raw.startsWith("'") && raw.endsWith("'")) {
    value = raw.slice(1, -1).replace(/''/g, "'");
  }
  return value.replace(CONTROL_CHARS, '').replace(/\s+/g, ' ').trim();
}

function truncate(text) {
  if (text.length <= MAX_DESCRIPTION_CHARS) return text;
  return `${text.slice(0, MAX_DESCRIPTION_CHARS - 1).trimEnd()}…`;
}

/** `deploy-preview` -> `deploy:preview` when commands/deploy.md exists; otherwise unchanged. */
function slashName(stem, stems) {
  const dash = stem.indexOf('-');
  if (dash > 0 && stems.has(stem.slice(0, dash))) return `${stem.slice(0, dash)}:${stem.slice(dash + 1)}`;
  return stem;
}

function renderSkill(stem, command, description) {
  return [
    '---',
    `name: ${SKILL_PREFIX}${stem}`,
    `description: ${JSON.stringify(`${description.replace(/[.\s]+$/, '')}. Use when the user types /${command}.`)}`,
    '---',
    '',
    `# /${command}`,
    '',
    `> Activates the BoomOpen Workflow Kit \`/${command}\` workflow.`,
    '',
    '## Rules',
    '',
    `1. **Load and follow**: \`${FRAMEWORK}/commands/${stem}.md\`. Load files from \`${FRAMEWORK}/rules/\` only when that command asks for them.`,
    '2. **Agents**: Spawn the kit roles with Codex native multi-agent (`~/.codex/agents/boomopen/*.toml`); they inherit your configured model.',
    `3. **Skills**: Resolve from \`${FRAMEWORK}/matrix-skills/compact-index.json\`, then read the matching \`SKILL.md\` under \`~/.codex/skills/\` or \`~/.codex/skills_library/\`.`,
    '',
    '<!-- Generated by .github/scripts/generate-codex-skills.js from commands/*.md. Do not edit by hand. -->',
    '',
  ].join('\n');
}

function renderOpenAiYaml(command, description, color) {
  return [
    'interface:',
    `  display_name: ${JSON.stringify(`/${command}`)}`,
    `  short_description: ${JSON.stringify(truncate(description.split(' — ').slice(0, 2).join(' — ')))}`,
    `  brand_color: ${JSON.stringify(color)}`,
    'policy:',
    '  allow_implicit_invocation: true',
    '',
  ].join('\n');
}

function buildOutputs() {
  const stems = fs.readdirSync(COMMANDS_DIR)
    .filter((name) => name.endsWith('.md'))
    .map((name) => name.slice(0, -3))
    .sort();
  const stemSet = new Set(stems);
  const outputs = new Map();
  for (const stem of stems) {
    const command = slashName(stem, stemSet);
    const description = truncate(readDescription(fs.readFileSync(path.join(COMMANDS_DIR, `${stem}.md`), 'utf8')) || `/${command} workflow.`);
    const base = command.split(':')[0];
    const dir = path.join(SKILLS_DIR, `${SKILL_PREFIX}${stem}`);
    outputs.set(path.join(dir, 'SKILL.md'), renderSkill(stem, command, description));
    outputs.set(path.join(dir, 'agents', 'openai.yaml'), renderOpenAiYaml(command, description, BRAND_COLORS[base] || DEFAULT_BRAND_COLOR));
  }
  return outputs;
}

function main() {
  const outputs = buildOutputs();
  const check = process.argv.includes('--check');
  const stale = [];
  for (const [file, content] of outputs) {
    let current = null;
    try {
      current = fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n');
    } catch (error) {
      if (!error || error.code !== 'ENOENT') throw error;
    }
    if (current === content) continue;
    stale.push(path.relative(REPO_ROOT, file));
    if (!check) {
      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.writeFileSync(file, content, 'utf8');
    }
  }
  const expectedDirs = new Set([...outputs.keys()].map((file) => path.relative(SKILLS_DIR, file).split(path.sep)[0]));
  const orphans = fs.readdirSync(SKILLS_DIR).filter((name) => name.startsWith(SKILL_PREFIX) && !expectedDirs.has(name));
  if (check) {
    if (stale.length || orphans.length) {
      console.error(`Codex skills are out of date (${stale.length} files, ${orphans.length} orphan folders). Run: node .github/scripts/generate-codex-skills.js`);
      return 1;
    }
    console.log(`Codex command skills are up to date (${outputs.size / 2} skills).`);
    return 0;
  }
  for (const orphan of orphans) fs.rmSync(path.join(SKILLS_DIR, orphan), { recursive: true, force: true });
  console.log(`Generated ${outputs.size / 2} Codex command skills (${stale.length} files written, ${orphans.length} orphans removed).`);
  return 0;
}

process.exitCode = main();
